/**
 * lucide-compat — the `lucide-react` names, served by Tecton icons.
 *
 * The shadcn-generated components in `src/components/` import this module by
 * name: the registry mirror rewrites the import the shadcn CLI would have
 * written to `lucide-react` (scripts/registry-mirror/icon-imports.mts), so CLI
 * managed code we do not edit still renders Tecton glyphs. The Tecton layer in
 * `src/tecton/` imports the named components from `@tecton/react/icons`
 * directly and does not go through here at all.
 *
 * The generated map below exports one Tecton component per lucide export name
 * (`ChevronDownIcon` → `./chevron-down`), including every alias spelling lucide
 * resolves to the same root (`Trash`, `TrashIcon`, `Trash2`, `Trash2Icon`).
 * There is **no** `export * from "lucide-react"` fallback any more: this module
 * exports what the icon manifest covers and nothing else, so a lucide name with
 * no Tecton icon behind it fails at build time instead of quietly rendering a
 * Lucide drawing. `lucide-react` is a devDependency of this package — only
 * `scripts/build-icons.mts` reads it, for lucide's root/alias table — and it is
 * not in the published dependency graph at all.
 *
 * This is still a compatibility surface, not the way to write new code. New
 * code imports the Tecton name from `@tecton/react/icons`
 * (`import { CloseIcon } from "@tecton/react/icons"`). Existing code that names
 * lucide identifiers and cannot be edited — a vendored example, a third-party
 * component — can alias the package at the bundler instead:
 *
 *   {
 *     name: "tecton-lucide-compat",
 *     enforce: "pre",
 *     async resolveId(source, importer) {
 *       if (source !== "lucide-react" || !importer) return null
 *       const r = await this.resolve("@tecton/react/icons/lucide-compat", importer, { skipSelf: true })
 *       return r?.id ?? null
 *     },
 *   }
 *
 * (Nothing in this repository needs that plugin: `apps/www` and
 * `@tecton/blocks` import `@tecton/react/icons` directly. The alias no longer
 * has to exclude `src/icons/` either — without the star re-export there is no
 * cycle to avoid.)
 *
 * `src/icons/lucide-compat.map.ts` is regenerated by `pnpm icons:build`
 * (scripts/build-icons.mts) — it scans `src/components` and `src/tecton` for the
 * identifiers imported from here (or from `lucide-react`) and pairs each with
 * the Tecton icon that stands in for it, and fails when one is not covered.
 * This file is hand-written and stable.
 */
export * from "./lucide-compat.map"
